INSERT INTO survey_activities (location_name, surveyor_name, field_notes, pain_points, potentials, geom) VALUES
('Halte Jembatan Gantung', 'Stefany Josefina Santono', 'Koridor arteri Daan Mogot dekat permukiman dan new development. Dilengkapi JPO menghubungkan kedua sisi jalan.', 'Penyeberangan jalan arteri padat dan penerangan malam hari perlu ditingkatkan.', 'Mendorong pertumbuhan ekonomi lokal perumahan baru dan memudahkan mobilitas pekerja komuter.', ST_SetSRID(ST_MakePoint(106.745, -6.155), 4326)),
('Halte Bundaran Senayan 2', 'Stefany Josefina Santono', 'Kawasan perkantoran protokol Sudirman, lanskap hijau rindang, papan rute digital, dan integrasi MRT.', 'Arus kendaraan depan halte sangat padat di jam sibuk.', 'Pusat mobilitas eksekutif dan pekerja komersial segitiga emas Jakarta.', ST_SetSRID(ST_MakePoint(106.8001, -6.2272), 4326)),
('Halte Rasuna Said', 'Stefany Josefina Santono', 'Kawasan bisnis HR Rasuna Said dekat Plaza Festival dan GOR Soemantri Brodjonegoro.', 'Penyeberangan jalan arteri Kuningan membutuhkan waktu tunggu lampu penyeberangan yang lama.', 'Titik transit utama koridor 6 terintegrasi dengan sentra olahraga dan hiburan.', ST_SetSRID(ST_MakePoint(106.8315, -6.2205), 4326)),
('Stasiun KRL Rawa Buntu', 'Theresia Ivana Marella', 'Simpul transit komuter Serpong-Tanah Abang dengan konektivitas ojek online dan kantong parkir.', 'Antrean penjemputan ojek online di jam sibuk memicu penyempitan jalan akses.', 'Menghubungkan masyarakat kawasan penyangga Serpong-Tangerang Selatan menuju Jakarta.', ST_SetSRID(ST_MakePoint(106.671, -6.321), 4326)),
('Stasiun MRT Lebak Bulus', 'Theresia Ivana Marella', 'Simpul transit utama Jakarta Selatan, terintegrasi jembatan langsung ke POINS Square dan Depo MRT.', 'Integrasi jalur pedestrian dari arah jalan non-protokol masih belum seragam.', 'Sentra TOD selatan Jakarta yang sangat potensial menampung integrasi rute feeder bus.', ST_SetSRID(ST_MakePoint(106.7745, -6.289), 4326)),
('Halte Bendungan Hilir 1', 'Stefany Josefina Santono', 'Koridor Sudirman dekat Stasiun MRT Benhil dengan trotoar pedestrian lebar dan akses jembatan.', 'Akses masuk gang permukiman Benhil padat dan trotoar dalam gang menyempit.', 'Konektivitas langsung pekerja SCBD dengan pusat jajanan dan hunian kos karyawan.', ST_SetSRID(ST_MakePoint(106.8192, -6.2155), 4326)),
('Halte Sampoerna Strategic', 'Stefany Josefina Santono', 'Kawasan bisnis padat Sudirman di depan gedung Sampoerna Strategic Square.', 'Akses transportasi di jam pulang kerja mengalami lonjakan antrean penumpang.', 'Melayani ribuan pekerja perkantoran multinasional dan institusi perbankan.', ST_SetSRID(ST_MakePoint(106.8205, -6.2185), 4326)),
('Halte Gelora Bung Karno 1', 'Stefany Josefina Santono', 'Pusat kegiatan olahraga, konser, dan perbelanjaan fX Sudirman. Akses trotoar ramah disabilitas dan sepeda.', 'Penuh sesak saat ada event olahraga nasional atau konser musik di kompleks GBK.', 'Titik ikonik transit warga urban Jakarta untuk rekreasi dan mobilitas harian.', ST_SetSRID(ST_MakePoint(106.8045, -6.2245), 4326)),
('Stasiun Tanah Abang', 'Theresia Ivana Marella', 'Pusat perdagangan tekstil terbesar di Asia Tenggara dan stasiun transit KRL terpadat.', 'Kepadatan pejalan kaki, pedagang kaki lima, dan moda ojol di area drop-off sangat tinggi.', 'Simpul ekonomi rakyat dengan perputaran transaksi harian mencapai miliaran rupiah.', ST_SetSRID(ST_MakePoint(106.8115, -6.1855), 4326))
